% exercise1.m
t = linspace(-1, 1, 4000);
Hvals = [1 3 9 25];

figure %[output:950aca47]
for i = 1:length(Hvals)
    H = Hvals(i);
    x = zeros(size(t));
    for k = 1:2:H
        x = x + (4/pi) * sin(2*pi*k*t) / k;
    end

    subplot(2, 2, i) %[output:950aca47]
    plot(t, x)
    grid on
    xlabel('Time (s)')
    ylabel('Amplitude')
    title(['H = ' num2str(H)])
end
sgtitle('Square wave approximation with increasing highest harmonic') %[output:950aca47]

exportgraphics(gcf, 'square-wave-comparison.png', 'Resolution', 300) %[output:950aca47]
t = linspace(-1, 1, 4000);
Hvals = [1 3 9 25];

figure %[output:1941e3fc]
for i = 1:length(Hvals) %[output:group:3c167a7e]
    H = Hvals(i);
    x = zeros(size(t));
    for k = 1:2:H
        x = x + (4/pi) * sin(2*pi*k*t) / k;
    end

    % --- new lines ---
    fprintf('H = %2d: max(x) = %.4f\n', H, max(x)); %[output:10e52937] %[output:3a9e85e5] %[output:17c33f76] %[output:2d6b35b9]

    mask = (t > 0) & (t < 0.25);          % only look just after t = 0
    [m, idx] = max(x(mask));
    tmask = t(mask);
    fprintf('        first peak after t=0 is at t = %.4f\n', tmask(idx)); %[output:85365709] %[output:19c84368] %[output:142254b1] %[output:15ef71a5]
    % -----------------

    subplot(2, 2, i) %[output:1941e3fc]
    plot(t, x)
    grid on
    xlabel('Time (s)')
    ylabel('Amplitude')e
    title(['H = ' num2str(H)])
end %[output:group:3c167a7e]
sgtitle('Square wave approximation with increasing highest harmonic') %[output:1941e3fc]
exportgraphics(gcf, 'square-wave-comparison.png', 'Resolution', 300) %[output:1941e3fc]

